            ww=np.tile(jw,450)
            f=fit.fit_physical(weights=ww,ridge=ridge,min_armature=floors)
            cvs=[]
            for e in np.unique(epi):
                fc=fit.fit_physical(weights=ww,ridge=ridge,min_armature=floors,selection=np.repeat(epi!=e,7))
                er=(A@fc['x']-b).reshape(-1,7)[epi==e]
                cvs.append(np.sqrt(np.mean(er**2,axis=0)))
            cv=np.array(cvs)
            entry={'floors':floors,'ridge':ridge,'jw':jw,'fit':f,'cv':cv}
